const places=features.filter(f=>f.tags.building&&(f.tags.name||f.tags.amenity==='library'||f.id==='618490372'));if(garden)places.push({tags:{name:'Library fountain & garden'},points:[garden.fountain]});places.forEach((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent=p.tags.name||(p.id==='618490372'?'Student Activity Centre':'Library');$('destination').append(o)});$('destination').onchange=e=>{if(e.target.value==='')return;const p=places[+e.target.value];selected=p.points[0];$('location').textContent=p.tags.name||(p.id==='618490372'?'Student Activity Centre':'Library');draw()};$('map').style.display='none';$('location').textContent='Drag to pan · Scroll to zoom';$('reset').onclick=()=>{zoom=1;offset=[0,0];selected=null;draw()};$('about').onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();c.onpointerdown=e=>{drag=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;offset[0]+=e.clientX-drag[0];offset[1]+=e.clientY-drag[1];drag=[e.clientX,e.clientY];draw()};c.onpointerup=c.onpointercancel=()=>drag=null;c.onwheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(4,zoom*Math.exp(-e.deltaY*.001)));draw()};window.addEventListener('resize',draw);draw();
